def clean(df):
    # Remove exact duplicate rows
    df = df.drop_duplicates()

    # Fix Category label variants
    df['Category'] = df['Category'].replace({
        'Office Suplies': 'Office Supplies',
        'Furnture': 'Furniture'
    })

    # Filter out invalid quantities (must be >= 1 per rules)
    df = df[df['Quantity'] >= 1].copy()

    return df

def answer(df):
    # Calculate average Price per Category
    avg_price = df.groupby('Category')['Price'].mean()
    return avg_price.to_dict()
